#include "kstationControllerStartupTablesRuntime.h"
#include "kstationControllerProgramAddressRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <memory>
#include <new>
#include <vector>
namespace {bool watch=false;uint64_t allocations=0;void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}class Original:public H8SEmulator{public:void histories(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t clocks;unsigned at;uint8_t value;bool write;};
template<class D>struct Tape{D&d;bool overlay=false,recording=false,context=false,trampoline=false;unsigned count=0,lcdBusy=2,phasePc=0;std::array<Event,16>events{};explicit Tape(D&s):d(s){}void record(unsigned a,uint8_t v,bool w){if(!recording||!w&&a>=phasePc&&a<phasePc+12||context&&a>=0xfffea0&&a<0xffff10||trampoline&&!w&&a>=0xfffd10&&a<0xfffd1c)return;check(count<events.size(),"Tape overflow");events[count++]={d.cycles,a,v,w};}uint8_t read(unsigned a){auto v=d.memory[a<0x10000&&overlay?0x400000+a:a];if(a==0xffffc7)v=lcdBusy?(--lcdBusy,0x80):0;record(a,v,false);return v;}void write(unsigned a,uint8_t v){record(a,v,true);d.memory[a]=v;if(a==0xffffcf)overlay=!(v&1);}};
struct OldBus:H8SDevice{Tape<Original>&t;explicit OldBus(Tape<Original>&s):t(s){}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct NewBus:kstation::ControllerResourceBus{Tape<kstation::ControllerDeviceState>&t;explicit NewBus(Tape<kstation::ControllerDeviceState>&s):t(s){}bool mapped(unsigned a)const override{return a<0x10000||a>=0x200000&&a<0x240000||a>=0x400000&&a<0x420000||a>=0xfffd00;}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct Fixture{std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::ControllerDeviceState>d=std::make_unique<kstation::ControllerDeviceState>();Tape<Original>x{*a};Tape<kstation::ControllerDeviceState>y{*d};OldBus xb{x};NewBus yb{y};kstation::ControllerStartupTablesRuntime tables;kstation::ControllerProgramAddressRuntime address;kstation::ControllerInterruptRuntime irq;uint64_t phases=0,io=0,shorts=0;void byte(unsigned at,unsigned v){a->memory[at&0xffffff]=d->memory[at&0xffffff]=uint8_t(v);}void word(unsigned at,unsigned v){byte(at,v>>8);byte(at+1,v);}void wide(unsigned at,unsigned v){for(unsigned i=0;i<4;++i)byte(at+i,v>>(8*(3-i)));}
Fixture(const std::vector<uint8_t>&rom){a->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);for(unsigned i=0;i<rom.size();++i)byte(0x400000+i,rom[i]);for(auto p:{std::pair{0,0x10000},std::pair{0x200000,0x40000},std::pair{0x400000,0x20000},std::pair{0xfffd00,0x300}})a->memmap(&xb,p.first,p.second);d->attachBus(&yb);check(irq.bindVerifiedFirmware(*d,rom.data(),rom.size()),"IRQ bind");check(tables.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Tables bind");check(address.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Address bind");}
void prepare(unsigned entry,unsigned flags){a->pc=a->makepc(entry);a->setSP(0xffff00);wide(0xffff00,0x3ae8);a->ccr=uint8_t(flags);a->histories(-1,-1);d->lastRead=d->lastWrite=-1;a->cycles=d->cycles=flags==255?~uint64_t(0)-7:100000;a->pending_irqs=d->pendingIrqs=flags==255?uint64_t(1)<<38:0;irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);x.recording=y.recording=true;}
void equal(unsigned pc){if(a->cycles!=d->cycles){std::fprintf(stderr,"PC%x clocks%llu/%llu\n",pc,a->cycles,d->cycles);throw std::runtime_error("Helper clocks");}if(x.count!=y.count){std::fprintf(stderr,"PC%x count%u/%u\n",pc,x.count,y.count);throw std::runtime_error("Helper IO count");}for(unsigned i=0;i<x.count;++i){auto&p=x.events[i];auto&q=y.events[i];check(p.clocks==q.clocks&&p.at==q.at&&p.value==q.value&&p.write==q.write,"Helper ordered IO");}io+=x.count;}
template<class R>void run(R&runtime){watch=true;for(unsigned i=0;runtime.active()&&i<3000;++i){auto pc=unsigned(a->getPC());x.context=y.context=true;x.phasePc=y.phasePc=pc&0xffffff;x.count=y.count=0;auto n=runtime.nextClocks(*d,irq);if(i<40||i%73==0){auto snapshot=runtime;auto cycle=d->cycles;int read=d->lastRead,write=d->lastWrite;for(unsigned b=0;b<n;++b){check(!runtime.advanceBefore(*d,irq,b).clocks,"Helper short accepted");check(!std::memcmp(&snapshot,&runtime,sizeof(runtime))&&cycle==d->cycles&&read==d->lastRead&&write==d->lastWrite&&!x.count&&!y.count,"Helper short mutated");++shorts;}}check(runtime.advanceBefore(*d,irq,n).clocks,"Helper refused");a->step();equal(pc);++phases;}watch=false;check(!runtime.active()&&a->getPC()==0x3ae8,"Helper runaway");for(auto p:{std::pair{0xc590,0x120},std::pair{0xfffd10,0x190},std::pair{0xffff10,0xf0}})check(!std::memcmp(a->memory+p.first,d->memory+p.first,p.second),"Helper memory differs");}
};}
void*operator new(size_t n){if(watch)++allocations;if(auto*p=std::malloc(n))return p;throw std::bad_alloc();}void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}
int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};uint64_t phases=0,io=0,shorts=0;unsigned tableCases=0,addressCases=0;Fixture f(rom);for(unsigned entry:{0x17bau,0x17c0u,0x1802u})for(unsigned rate:{0u,1u,1000u,0x8000u,0xffffu})for(unsigned flags:{0u,0xffu}){f.prepare(entry,flags);f.word(0xbf98,rate);check(f.tables.start(entry==0x17ba?kstation::StartupTablesTask::Kind::Both:entry==0x17c0?kstation::StartupTablesTask::Kind::Delay:kstation::StartupTablesTask::Kind::Samples),"Tables start");f.run(f.tables);++tableCases;}
for(unsigned flags=0;flags<256;++flags){f.prepare(0x17ba,flags);f.word(0xbf98,1000+flags);check(f.tables.start(),"Tables start");f.run(f.tables);++tableCases;}
for(unsigned bank=0;bank<256;++bank)for(unsigned program:{0u,99u,255u})for(unsigned mode:{0u,1u,255u}){f.prepare(0x4cb8,bank);f.byte(0xcd82,bank);f.byte(0xcd83,program);f.byte(0xcd77,mode);check(f.address.start(),"Address start");f.run(f.address);check(f.address.value()==uint32_t(f.a->reg32(0)),"Address result differs");++addressCases;}
for(unsigned source:{0xcd82u,0x21fe00u,0xffffffu})for(unsigned bank:{0u,1u,255u}){f.prepare(0x4c36,255);f.byte(source,bank);f.byte(source+1,0xfe);f.a->reg32(0)=int32_t(source);check(f.address.startIndex(source),"Index start");f.run(f.address);check(f.address.value()==uint16_t(f.a->reg16(0)),"Index result differs");++addressCases;}
check(!allocations,"Helper processing allocation");std::printf("{\"passed\":true,\"table_graphs\":%u,\"address_graphs\":%u,\"native_phases\":%llu,\"ordered_io\":%llu,\"short_budgets\":%llu,\"processing_allocations\":%llu}\n",tableCases,addressCases,f.phases,f.io,f.shorts,allocations);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
